/**
 * n8n Code node — Workflow B
 * Parse config tab once and store for all parallel ranking branches.
 * Wire: Read config tab B -> Store ranking config -> Read unique_jobs tab
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function getConfigValue(rows, key) {
  const row = rows.find((item) => clean(item.json.key).toLowerCase() === key);
  return clean(row?.json.value || '');
}

const rows = $input.all();
const staticData = $getWorkflowStaticData('global');

staticData.rankingConfig = {
  openai_api_key: getConfigValue(rows, 'openai_api_key'),
  openai_model: getConfigValue(rows, 'openai_model') || 'gpt-4o-mini',
  llm_rank_prompt: getConfigValue(rows, 'llm_rank_prompt'),
  systems_rank_prompt: getConfigValue(rows, 'systems_rank_prompt'),
  mechanical_rank_prompt: getConfigValue(rows, 'mechanical_rank_prompt'),
  controls_rank_prompt: getConfigValue(rows, 'controls_rank_prompt'),
  systems_resume_text: getConfigValue(rows, 'systems_resume_text'),
  mechanical_resume_text: getConfigValue(rows, 'mechanical_resume_text'),
  controls_resume_text: getConfigValue(rows, 'controls_resume_text'),
  blocklist: getConfigValue(rows, 'blocklist'),
};

return [{
  json: {
    config_loaded: true,
    config_rows: rows.length,
  },
}];

/**
 * n8n Code node — Workflow B
 * Remove jobs whose title/JD matches config blocklist (ITAR, citizenship, etc.)
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

const defaultBlocklist = [
  'itar',
  'export control',
  'u.s. citizen',
  'us citizen',
  'united states citizen',
  'citizenship required',
  'must be a citizen',
  'must be a u.s. citizen',
  'active secret clearance',
  'secret clearance',
  'top secret clearance',
  'ability to obtain clearance',
];

const staticData = $getWorkflowStaticData('global');
const configured = splitTerms(staticData.rankingConfig?.blocklist || '');
const blocklist = configured.length ? configured : defaultBlocklist;

function isRestricted(job) {
  const haystack = clean([
    job.title,
    job.full_jd,
    job.location,
    job.company,
  ].join(' ')).toLowerCase();

  return blocklist.some((term) => haystack.includes(term));
}

const out = [];

for (const item of $input.all()) {
  const job = item.json || {};
  if (isRestricted(job)) continue;
  out.push(item);
}

return out;

/**
 * n8n Code node — Workflow B
 * Set BUCKET below to: systems | mechanical | controls
 */

const BUCKET = 'systems';

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

return $input.all().filter((item) => {
  const bucket = clean(item.json?.bucket_selected).toLowerCase();
  return bucket === BUCKET;
});

/**
 * n8n Code node — Workflow B
 * Sort ranked jobs by score descending (highest first).
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

const rows = $input.all();

rows.sort((a, b) => {
  const scoreA = Number(a.json?.score) || 0;
  const scoreB = Number(b.json?.score) || 0;
  return scoreB - scoreA;
});

return rows.map((item, index) => ({
  json: {
    ...(item.json || {}),
    rank: index + 1,
  },
}));

