function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function rowKey(row) {
  const json = row.json || {};
  return clean(
    json.key ||
    json.Key ||
    json.KEY ||
    json.A ||
    json['Column A'] ||
    ''
  ).toLowerCase();
}

function rowValue(row) {
  const json = row.json || {};
  return clean(
    json.value ||
    json.Value ||
    json.VALUE ||
    json.B ||
    json['Column B'] ||
    ''
  );
}

function getConfigValue(rows, key) {
  const wanted = clean(key).toLowerCase();
  const row = rows.find((item) => rowKey(item) === wanted);
  return row ? rowValue(row) : '';
}

function getConfigValueAny(rows, keys) {
  for (const key of keys) {
    const value = getConfigValue(rows, key);
    if (value) return value;
  }
  return '';
}

